        self.assertBad("2024-01-01 food ٥", 1)
        self.assertBad("٢024-01-01 food 5", 1)

    def test_line_number_counts_blank_and_comment_lines(self):
        text = "# header\n\n2024-01-01 a 1\n\n# c\n2024-01-02 b 12.505\n"
        self.assertBad(text, 6)

    def test_line_number_with_crlf(self):
        self.assertBad("2024-01-01 a 1\r\n\r\nbad\r\n", 3)

    def test_message_names_amount(self):
        exc = self.assertBad("\n\n\n2024-01-01 a 12.505", 4)
        self.assertEqual(str(exc), "line 4: invalid amount '12.505'")

    def test_first_error_reported(self):
        self.assertBad("bad\nworse\n", 1)


