    def setUp(self):
        tmp = tempfile.TemporaryDirectory()
        self.addCleanup(tmp.cleanup)
        self.dir = tmp.name
        self.path = os.path.join(self.dir, "house.txt")
        self.write(HOUSE)

    def write(self, text, name="house.txt"):
        path = os.path.join(self.dir, name)
        with open(path, "w", encoding="utf-8", newline="") as f:
            f.write(text)
        return path

    def read(self, name="house.txt"):
        with open(os.path.join(self.dir, name), "rb") as f:
            return f.read()

class Errors(Base):
