            code, out, err = run([cmd, os.path.join(self.dir, "nope.txt")])
            self.assertEqual((code, out), (2, ""), cmd)
            self.assertTrue(err)

    def test_directory_exit_2(self):
        self.assertEqual(run(["balance", self.dir])[::2][0], 2)

